import{_ as a,o,c as i,ag as s}from"./chunks/framework.Fczl-Cb9.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1771746637000}'),t={name:"faq.md"};function n(l,e,d,r,h,c){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-cloding" tabindex="-1">What is cloding? <a class="header-anchor" href="#what-is-cloding" aria-label="Permalink to &quot;What is cloding?&quot;">​</a></h3><p>cloding is a universal wrapper that lets you run <strong>5 coding CLI tools</strong> — Claude Code, Gemini CLI, Codex CLI, GitHub Copilot CLI, and OpenCode — with any model. Route through OpenRouter for cheap multi-model access, use your own API keys, or link your paid subscription.</p><h3 id="is-cloding-a-fork-of-claude-code" tabindex="-1">Is cloding a fork of Claude Code? <a class="header-anchor" href="#is-cloding-a-fork-of-claude-code" aria-label="Permalink to &quot;Is cloding a fork of Claude Code?&quot;">​</a></h3><p>No. cloding doesn&#39;t modify, patch, or fork any CLI tool. It starts the chosen tool with the right configuration and handles model selection. Zero modified binaries.</p><h3 id="which-cli-tools-does-cloding-support" tabindex="-1">Which CLI tools does cloding support? <a class="header-anchor" href="#which-cli-tools-does-cloding-support" aria-label="Permalink to &quot;Which CLI tools does cloding support?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Install</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>npm install -g @anthropic-ai/claude-code</code></td></tr><tr><td>Gemini CLI</td><td><code>npm install -g @google/gemini-cli</code></td></tr><tr><td>Codex CLI</td><td><code>npm install -g @openai/codex</code></td></tr><tr><td>GitHub Copilot CLI</td><td><code>npm install -g @github/copilot</code></td></tr><tr><td>OpenCode</td><td><code>npm install -g opencode-ai</code></td></tr></tbody></table><h3 id="do-i-need-all-5-tools-installed" tabindex="-1">Do I need all 5 tools installed? <a class="header-anchor" href="#do-i-need-all-5-tools-installed" aria-label="Permalink to &quot;Do I need all 5 tools installed?&quot;">​</a></h3><p>No. You only need Claude Code (the default) to get started. Install other tools as you want to use them.</p><h3 id="do-i-need-an-api-key" tabindex="-1">Do I need an API key? <a class="header-anchor" href="#do-i-need-an-api-key" aria-label="Permalink to &quot;Do I need an API key?&quot;">​</a></h3><p>It depends on the mode:</p><ul><li><strong>OpenRouter mode</strong> (default) — Yes, you need an <code>OPENROUTER_API_KEY</code></li><li><strong>Direct API mode</strong> (<code>-a</code> suffix) — Yes, you need the provider&#39;s API key</li><li><strong>Paid plan mode</strong> (<code>-p</code> suffix) — No, uses your existing subscription</li></ul><h3 id="is-cloding-free" tabindex="-1">Is cloding free? <a class="header-anchor" href="#is-cloding-free" aria-label="Permalink to &quot;Is cloding free?&quot;">​</a></h3><p>cloding itself is free and open source. You pay for model usage through your chosen auth mode — OpenRouter tokens, direct API usage, or your paid subscription.</p><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h2><h3 id="which-model-should-i-use" tabindex="-1">Which model should I use? <a class="header-anchor" href="#which-model-should-i-use" aria-label="Permalink to &quot;Which model should I use?&quot;">​</a></h3><p>For most tasks, <strong>Qwen 3 Coder</strong> (the default) is the best value — it&#39;s 42x cheaper than Claude Opus and handles day-to-day coding well. For complex architecture or planning, switch to <strong>Sonnet</strong> or <strong>Opus</strong>. If you have a paid plan (Claude Max, ChatGPT, Gemini), use that for zero per-token cost. See <a href="/cloding/models">Models &amp; Pricing</a> for a full comparison.</p><h3 id="what-are-the-3-auth-modes" tabindex="-1">What are the 3 auth modes? <a class="header-anchor" href="#what-are-the-3-auth-modes" aria-label="Permalink to &quot;What are the 3 auth modes?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Suffix</th><th>Mode</th><th>Example</th></tr></thead><tbody><tr><td><em>(none)</em> or <code>-o</code></td><td>OpenRouter</td><td><code>cloding -m sonnet</code></td></tr><tr><td><code>-a</code></td><td>Direct API</td><td><code>cloding -m sonnet-a</code></td></tr><tr><td><code>-p</code></td><td>Paid plan</td><td><code>cloding -m sonnet-p</code></td></tr></tbody></table><p>See <a href="/cloding/authentication">Authentication</a> for details.</p><h3 id="can-i-use-claude-models-through-cloding" tabindex="-1">Can I use Claude models through cloding? <a class="header-anchor" href="#can-i-use-claude-models-through-cloding" aria-label="Permalink to &quot;Can I use Claude models through cloding?&quot;">​</a></h3><p>Yes. All Claude models are available through OpenRouter, direct API, or your Claude Max subscription:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonnet</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # via OpenRouter</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonnet-a</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # via Anthropic API</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonnet-p</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # via Claude Max subscription</span></span></code></pre></div><h3 id="can-i-use-non-claude-tools" tabindex="-1">Can I use non-Claude tools? <a class="header-anchor" href="#can-i-use-non-claude-tools" aria-label="Permalink to &quot;Can I use non-Claude tools?&quot;">​</a></h3><p>Yes. cloding supports Gemini CLI, Codex CLI, Copilot CLI, and OpenCode:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gemini-3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Gemini CLI with your Gemini plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex-5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Codex CLI with your ChatGPT plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Copilot CLI</span></span></code></pre></div><h3 id="do-all-models-work-equally-well" tabindex="-1">Do all models work equally well? <a class="header-anchor" href="#do-all-models-work-equally-well" aria-label="Permalink to &quot;Do all models work equally well?&quot;">​</a></h3><p>No. Claude Code relies on tool use (function calling) to edit files and run commands. Some models handle this better than others. Qwen, DeepSeek, Claude, Gemini, and Codex all work well. Smaller or older models may struggle. See <a href="/cloding/custom-models#models-that-support-tool-use">Custom Models — Tool Use</a>.</p><h3 id="can-i-use-models-not-listed-in-the-shortcuts" tabindex="-1">Can I use models not listed in the shortcuts? <a class="header-anchor" href="#can-i-use-models-not-listed-in-the-shortcuts" aria-label="Permalink to &quot;Can I use models not listed in the shortcuts?&quot;">​</a></h3><p>Yes. Pass any OpenRouter model ID directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meta-llama/llama-4-scout</span></span></code></pre></div><p>Browse all available models at <a href="https://openrouter.ai/models" target="_blank" rel="noreferrer">openrouter.ai/models</a>.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><h3 id="how-much-does-a-typical-session-cost" tabindex="-1">How much does a typical session cost? <a class="header-anchor" href="#how-much-does-a-typical-session-cost" aria-label="Permalink to &quot;How much does a typical session cost?&quot;">​</a></h3><p>With the default model (Qwen 3 Coder), a 30-minute coding session costs approximately <strong>$0.07</strong>. With a paid plan (<code>-p</code> suffix), it costs <strong>$0</strong> per token. See the <a href="/cloding/models#cost-comparison">cost comparison table</a>.</p><h3 id="is-there-a-free-tier" tabindex="-1">Is there a free tier? <a class="header-anchor" href="#is-there-a-free-tier" aria-label="Permalink to &quot;Is there a free tier?&quot;">​</a></h3><p>OpenRouter sometimes offers free credits for new accounts. Check <a href="https://openrouter.ai" target="_blank" rel="noreferrer">openrouter.ai</a> for current promotions. Some models on OpenRouter also have free tiers. Paid plan models (<code>-p</code> suffix) cost $0 per token if you have a subscription.</p><h3 id="how-do-i-monitor-my-spending" tabindex="-1">How do I monitor my spending? <a class="header-anchor" href="#how-do-i-monitor-my-spending" aria-label="Permalink to &quot;How do I monitor my spending?&quot;">​</a></h3><p>Check your usage on the <a href="https://openrouter.ai/activity" target="_blank" rel="noreferrer">OpenRouter dashboard</a>. You can also set spending limits on your API key.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><h3 id="is-my-code-sent-to-third-parties" tabindex="-1">Is my code sent to third parties? <a class="header-anchor" href="#is-my-code-sent-to-third-parties" aria-label="Permalink to &quot;Is my code sent to third parties?&quot;">​</a></h3><p>Yes. Your code is sent to the API provider for the model you&#39;re using:</p><ul><li><strong>OpenRouter models</strong> — Sent to OpenRouter, which routes to the model provider</li><li><strong>Direct API models</strong> (<code>-a</code>) — Sent directly to the provider (Anthropic, Google, OpenAI)</li><li><strong>Paid plan models</strong> (<code>-p</code>) — Sent through the CLI tool&#39;s native channel</li></ul><p>Review each provider&#39;s privacy policy for details.</p><h3 id="is-docker-mode-fully-secure" tabindex="-1">Is Docker mode fully secure? <a class="header-anchor" href="#is-docker-mode-fully-secure" aria-label="Permalink to &quot;Is Docker mode fully secure?&quot;">​</a></h3><p>Docker mode is a practical safety layer, not a security guarantee. It prevents the most common risks (agent reading secrets, destructive commands on host), but containers still have network access and can modify files in the mounted workspace. See <a href="/cloding/docker#security-model">Docker — Security Model</a>.</p><h3 id="can-cloding-access-my-api-keys-and-secrets" tabindex="-1">Can cloding access my API keys and secrets? <a class="header-anchor" href="#can-cloding-access-my-api-keys-and-secrets" aria-label="Permalink to &quot;Can cloding access my API keys and secrets?&quot;">​</a></h3><p>In normal mode, the agent has the same access as your terminal — including <code>.env</code> files, SSH keys, and anything else in your home directory. Use <a href="/cloding/docker">Docker mode</a> to isolate the agent from sensitive files.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><h3 id="does-cloding-work-on-windows" tabindex="-1">Does cloding work on Windows? <a class="header-anchor" href="#does-cloding-work-on-windows" aria-label="Permalink to &quot;Does cloding work on Windows?&quot;">​</a></h3><p>Yes. cloding works anywhere the underlying CLI tools and Node.js work — macOS, Linux, and Windows (including WSL).</p><h3 id="does-cloding-work-with-vs-code" tabindex="-1">Does cloding work with VS Code? <a class="header-anchor" href="#does-cloding-work-with-vs-code" aria-label="Permalink to &quot;Does cloding work with VS Code?&quot;">​</a></h3><p>cloding is a terminal tool, not an IDE extension. Run it in VS Code&#39;s integrated terminal alongside your editor.</p><h3 id="can-i-use-cloding-in-ci-cd" tabindex="-1">Can I use cloding in CI/CD? <a class="header-anchor" href="#can-i-use-cloding-in-ci-cd" aria-label="Permalink to &quot;Can I use cloding in CI/CD?&quot;">​</a></h3><p>Yes. Use the <code>-p</code> flag for non-interactive mode:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;run the test suite and fix any failing tests&quot;</span></span></code></pre></div><p>Set <code>OPENROUTER_API_KEY</code> as a CI secret.</p><h3 id="does-cloding-work-with-all-cli-tool-features" tabindex="-1">Does cloding work with all CLI tool features? <a class="header-anchor" href="#does-cloding-work-with-all-cli-tool-features" aria-label="Permalink to &quot;Does cloding work with all CLI tool features?&quot;">​</a></h3><p>Yes. cloding passes through all flags and features to the underlying CLI tool. Anything the tool supports, cloding supports.</p><h3 id="can-i-use-cloding-with-mcp-servers" tabindex="-1">Can I use cloding with MCP servers? <a class="header-anchor" href="#can-i-use-cloding-with-mcp-servers" aria-label="Permalink to &quot;Can I use cloding with MCP servers?&quot;">​</a></h3><p>Yes. Claude Code&#39;s MCP (Model Context Protocol) configuration works with cloding. Set up your MCP servers as you normally would with Claude Code.</p><h3 id="does-cloding-work-with-account-linking" tabindex="-1">Does cloding work with account linking? <a class="header-anchor" href="#does-cloding-work-with-account-linking" aria-label="Permalink to &quot;Does cloding work with account linking?&quot;">​</a></h3><p>Yes. Gemini CLI and Copilot CLI support account linking. Sign in to each CLI once, and cloding will use your linked account:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gemini</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Sign in once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Sign in once</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Then use with cloding</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gemini-3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # Uses linked Gemini account</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Uses linked Copilot account</span></span></code></pre></div>`,65)])])}const g=a(t,[["render",n]]);export{u as __pageData,g as default};
